using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [TestMethod]
    public async Task Greeting_IsRelevantAndCoherent()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Greeting_IsRelevantAndCoherent));

        var chatClient = scenario.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task FactualQuestion_IsAccurate()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsAccurate));

        var chatClient = scenario.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), ".evaluation-results"),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // Use the same model endpoint configured in the AppHost for evaluation.
        // In CI, set the AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? "test-key";

        var client = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey));

        IChatClient chatClient = client.GetChatClient("gpt-4o-mini").AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

